  '🔗 ' + (ex.url || 'Check n8n dashboard')
].join('\n');
return {json: {
  messaging_product: 'whatsapp',
  to: '+9779845670262',
  type: 'text',
  text: {preview_url: false, body: msg}
}};

// Collect all AI responses and pick the first valid one
const items = $input.all();

const required = [
  'facebook_post_caption', 'instagram_post_caption',
  'youtube_video_title', 'tiktok_video_caption'
];

// Default fallback content used if ALL AIs fail
const fallback = {
  facebook_post_caption: '🎥 Check out this amazing video! Drop a comment below 👇 #video #content #viral',
  facebook_reels_caption: '🔥 Watch this! #reels #viral #trending',
  facebook_story_text: '🎬 New video is out! Swipe up!',
  instagram_post_caption: '✨ New video just dropped! Watch till the end 🔥\n\nDrop your thoughts below 👇\n\n#video #content #viral #reels #instagram',
  instagram_reels_caption: '🔥 This one hits different! Watch till end ✨ #reels #viral #trending #fyp',
  instagram_story_text: '🎬 New video alert! 🔔',
  youtube_video_title: 'You Need to Watch This Video',
  youtube_video_description: 'Watch this amazing video! Subscribe for more content like this.\n\n#video #content',
  youtube_video_tags: ['video', 'content', 'viral', 'youtube', 'watch'],
  youtube_shorts_title: 'Watch This #Shorts',
  tiktok_video_caption: '🔥 Watch till end! #fyp #viral #trending',
  tiktok_story_text: 'New video! 🎬',
  content_summary: 'An engaging video worth watching.',
  hashtags: ['#video', '#content', '#viral', '#trending', '#social']
};

for (const item of items) {
  // Skip obvious error items
  if (item.json.error && !item.json.choices && !item.json.candidates) continue;

  let rawText = null;

  // OpenAI / OpenRouter format
  if (item.json.choices?.[0]?.message?.content) {
    rawText = item.json.choices[0].message.content;
  }
  // Gemini format
  else if (item.json.candidates?.[0]?.content?.parts?.[0]?.text) {
    rawText = item.json.candidates[0].content.parts[0].text;
  }

  if (!rawText) continue;

  // Strip markdown code fences
  rawText = rawText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

  // Extract JSON from response if wrapped in other text
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) rawText = jsonMatch[0];

  let parsed;
  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    continue;
  }

  // Validate required fields exist
  const valid = required.every(f => parsed[f] && typeof parsed[f] === 'string');
  if (!valid) continue;

  // Ensure arrays are arrays
  if (!Array.isArray(parsed.youtube_video_tags)) parsed.youtube_video_tags = ['video', 'content'];
  if (!Array.isArray(parsed.hashtags)) parsed.hashtags = ['#video', '#content'];

  return [{json: {...parsed, _aiSource: item.json.model || 'ai_provider', _aiOk: true}}];
}

// All AIs failed — use defaults
return [{json: {...fallback, _aiSource: 'fallback_defaults', _aiOk: false,
  _aiError: 'All AI providers failed — using default content'}}];

// Pull AI content (validated) and file info
const ai  = $('🧠 CODE: Pick Best AI Response').first().json;
const fi  = $('⚙️ SET: File Info & Config').first().json;

// Validate AI fields and fill any gaps
const ensure = (v, d) => (v && typeof v === 'string' && v.length > 2) ? v : d;
const ensureArr = (v, d) => (Array.isArray(v) && v.length) ? v : d;

const content = {
  facebook_post_caption:     ensure(ai.facebook_post_caption,   '🎥 New video! Check it out 🔥 #video #content'),
  facebook_reels_caption:    ensure(ai.facebook_reels_caption,  '🔥 Watch this reel! #reels #viral'),
  facebook_story_text:       ensure(ai.facebook_story_text,     '🎬 New video! Tap to watch'),
  instagram_post_caption:    ensure(ai.instagram_post_caption,  '✨ New content just dropped! #video #content #viral'),
  instagram_reels_caption:   ensure(ai.instagram_reels_caption, '🔥 Watch till end! #reels #fyp #viral'),
  instagram_story_text:      ensure(ai.instagram_story_text,    '🎬 New video alert!'),
  youtube_video_title:       ensure(ai.youtube_video_title,     fi.fileName.replace(/\.[^.]+$/, '')),
  youtube_video_description: ensure(ai.youtube_video_description,
    'Watch this video! Subscribe for more content.\n\n' + (fi.description || '')),
  youtube_video_tags:        ensureArr(ai.youtube_video_tags,   ['video', 'content', 'viral', 'youtube']),
  youtube_shorts_title:      ensure(ai.youtube_shorts_title,    'Watch This #Shorts'),
  tiktok_video_caption:      ensure(ai.tiktok_video_caption,    '🔥 #fyp #viral #trending'),
